import UIKit

@main
class AppDelegate: UIResponder, UIApplicationDelegate {
    var window: UIWindow?
    func application(_ application: UIApplication, didFinishLaunchingWithOptions launchOptions: [UIApplication.LaunchOptionsKey: Any]? = nil) -> Bool {
        window = UIWindow(frame: UIScreen.main.bounds)
        window?.rootViewController = UIViewController()
        window?.makeKeyAndVisible()
        return true
    }
}

import XCTest

final class OpenProfileTests: XCTestCase {
    func testOpenProfile() throws {
        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
        app.activate()
        _ = app.windows.firstMatch.waitForExistence(timeout: 10)
        Thread.sleep(forTimeInterval: 2)

        var tapped = false
        for label in ["Profile", "profile", "Me", "My Profile", "Avatar"] {
            let b = app.buttons[label]
            if b.exists {
                b.tap()
                tapped = true
                break
            }
        }
        if !tapped {
            let tb = app.tabBars.firstMatch
            if tb.exists {
                let btns = tb.buttons
                if btns.count > 0 {
                    btns.element(boundBy: btns.count - 1).tap()
                    tapped = true
                }
            }
        }
        if !tapped {
            let w = app.windows.firstMatch
            let f = w.frame
            let dx = f.width * 0.89
            let dy = f.height * 0.926
            w.coordinate(withNormalizedOffset: CGVector(dx: 0, dy: 0))
                .withOffset(CGVector(dx: dx, dy: dy)).tap()
        }
        Thread.sleep(forTimeInterval: 3)
        try? app.debugDescription.write(toFile: "/tmp/bsky_hierarchy.txt", atomically: true, encoding: .utf8)
    }
}

